  `PM` varchar(1) DEFAULT NULL,
  PRIMARY KEY (`S_No`)
) ENGINE=InnoDB AUTO_INCREMENT=23167 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;






CREATE TABLE `class_attendance` (
  `S_No` int(11) NOT NULL AUTO_INCREMENT,
  `Date` varchar(50) NOT NULL,
  `Class` varchar(50) NOT NULL,
  `Section` varchar(10) NOT NULL,
  `AM_Status` enum('Submitted') DEFAULT NULL,
  `PM_Status` enum('Submitted') DEFAULT NULL,
