  `PM_Punch_Time` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`S_No`)
) ENGINE=InnoDB AUTO_INCREMENT=382 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;






CREATE TABLE `class_wise_examination` (
  `S_No` int(11) NOT NULL AUTO_INCREMENT,
  `Class` varchar(15) NOT NULL,
  `Exam` varchar(50) NOT NULL,
  `Max_Marks` int(11) NOT NULL,
  PRIMARY KEY (`S_No`)
) ENGINE=InnoDB AUTO_INCREMENT=110 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;






CREATE TABLE `class_wise_subjects` (
  `S_No` int(11) NOT NULL AUTO_INCREMENT,
  `Class` varchar(15) NOT NULL,
  `Exam` varchar(50) NOT NULL,
  `Subjects` varchar(20) NOT NULL,
  `Max_Marks` int(11) NOT NULL,
  PRIMARY KEY (`S_No`)
) ENGINE=InnoDB AUTO_INCREMENT=685 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;






CREATE TABLE `commit_date` (
  `S_No` int(11) NOT NULL AUTO_INCREMENT,
